# Guarded wrapper
# ------------------------------------------------------------------------------


def recommended_max_tokens(include_prefill: bool, floor: int = 0) -> int:
    """Largest batch (tokens) to keep on the fast path; bigger falls back to
    NCCL. Covers the spec-decode batch plus, if ``include_prefill``, a prefill
    chunk. Returns ``floor`` if server args are unavailable."""
    try:

        def g(value) -> int:
            return value if isinstance(value, int) and value > 0 else 0

        schedule, spec = get_schedule(), get_spec()
        tokens = g(schedule.max_running_requests) * max(
            g(spec.speculative_num_draft_tokens), g(spec.speculative_eagle_topk), 1
        )
        if include_prefill:
            tokens = max(
                tokens, g(schedule.chunked_prefill_size), g(schedule.max_prefill_tokens)
            )
        return max(tokens, floor)
    except Exception:
        return floor


class MultimemAllGatherer:
    """Guarded multimem all-gather (last dim) with NCCL fallback; the single
    entry point for every caller. Owns one symmetric buffer built lazily on the
    first eager call, and uses the kernel only when the input fits its
    dtype/shape/alignment contract. Guards use TP-replicated quantities so all
    ranks pick the same path. ``skip_entry_sync=True`` drops the entry barrier;
    only safe when a cross-rank sync sits between consecutive calls."""

    _UNINIT = object()

    def __init__(
        self,
        max_tokens: int,
        *,
        enabled: bool = True,
        skip_entry_sync: bool = False,
    ):
        self._max_tokens = int(max_tokens)
        self._skip_entry_sync = skip_entry_sync
        # None => always NCCL; _UNINIT => build on first eager call.
        self._state = self._UNINIT if enabled else None
        if self._state is self._UNINIT:
            # Lazy import avoids a module-load dependency on the distributed facade.
            from sglang.srt.distributed.parallel_state import (
                get_tp_group,
                in_the_same_node_as,
            )

            tp_group = get_tp_group()
            # Only probe node topology when the deployment can actually span
            # nodes. Check world_size first so a TP=1 gatherer short-circuits
            # before reading the parallel config (which may be unpublished on
            # offline paths). On a single node every TP rank is co-located, so skip the
            # in_the_same_node_as() all-reduce, which can segfault under some
            # EP/mooncake setups, and keep multimem enabled.
            if (
                tp_group.world_size > 1
                and get_parallel().nnodes > 1
                and not all(in_the_same_node_as(tp_group.cpu_group, source_rank=0))
            ):
                logger.warning(
                    "multimem all-gather disabled because the TP group spans "
                    "across nodes."
                )
                self._state = None

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        state = self._state
        if state is self._UNINIT:
            state = self._build(x)
            if state is not self._UNINIT:
                self._state = state
        if (
            state is not None
            and state is not self._UNINIT
            and x.dtype == torch.bfloat16
            and x.dim() == 2
            and x.is_contiguous()
            and 0 < x.shape[0] <= state.max_token_num
            and x.data_ptr() % 16 == 0
            and x.shape[-1] * state.world_size <= state.hidden_dim
        ):
            return all_gather_inner(
                state,
                x,
                tp_hidden_dim=x.shape[-1] * state.world_size,
                skip_entry_sync=self._skip_entry_sync,
                safe=False,
            )
        # Lazy import avoids a module-load dependency on the distributed facade.
        from sglang.srt.distributed import tensor_model_parallel_all_gather

        return tensor_model_parallel_all_gather(x, dim=-1)

    def _build(self, x: torch.Tensor):
        if x.dim() != 2 or x.dtype != torch.bfloat16:
            return None
        if torch.cuda.is_available() and torch.cuda.is_current_stream_capturing():
            # Can't allocate under capture; retry later.
            return self._UNINIT
        if x.shape[-1] % _NUMEL_PER_THREAD != 0:
            return None
        try:
            from sglang.srt.distributed.parallel_state import get_tp_group

            tp_group = get_tp_group()
            if tp_group.world_size <= 1:
                return None
            state = create_state(
                group=tp_group.device_group,
                rank_in_group=tp_group.rank_in_group,
                max_tokens=self._max_tokens,
                hidden_size=x.shape[-1] * tp_group.world_size,
            )
            if state.symm_mem_hdl.multicast_ptr == 0:
                # No multicast for this world size / arch; multimem.st would
                # write nowhere. Fall back to NCCL.
                logger.warning(
                    "multimem all-gather disabled (no multicast for world_size=%d)",
                    tp_group.world_size,
                )
                return None
            return state
        except Exception as e:
            logger.warning("multimem all-gather disabled (%s)", e)
            return None

"""All-gather of a vocab-parallel row block across a TP group.

Every implementation takes this rank's ``[rows, local_width]`` slice and returns
``[rows, world_size * local_width]`` with the ranks' slices side by side, the
layout ``GroupCoordinator.all_gather(dim=-1)`` produces.
"""

from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from typing import Optional, Tuple

import torch

logger = logging.getLogger(__name__)


class VocabGather(ABC):
    """``[rows, local] -> [rows, world_size * local]``, ranks side by side."""

    @abstractmethod
    def __call__(self, local: torch.Tensor) -> torch.Tensor: ...

    @abstractmethod
    def gather_stacked(self, local: torch.Tensor) -> torch.Tensor:
        """Gather compact row blocks as [world_size * rows, local_width]."""
        ...


class LocalVocabGather(VocabGather):
    """A group of one: the slice is the whole row."""

    def __call__(self, local: torch.Tensor) -> torch.Tensor:
        return local

    def gather_stacked(self, local: torch.Tensor) -> torch.Tensor:
        return local


class NcclVocabGather(VocabGather):
    """The group coordinator's all_gather along the last dim (NCCL ring)."""

    def __init__(self, group) -> None:
        self.group = group

    def __call__(self, local: torch.Tensor) -> torch.Tensor:
        return self.group.all_gather(local, dim=-1)

    def gather_stacked(self, local: torch.Tensor) -> torch.Tensor:
        return self.group.all_gather(local, dim=0)


# Collective: every rank of the group must call this, in the same order, outside
# CUDA-graph capture. The returned multicast alias is 0 when the group has none.
def _alloc_symm(
    group, shape: Tuple[int, int], dtype: torch.dtype
) -> Tuple[torch.Tensor, int]:
    from torch._C._distributed_c10d import _SymmetricMemory

    # a GroupCoordinator names the allocation by its cpu_group, as
    # CustomAllReduceV2 does; a torch process group names it itself
    pg = getattr(group, "cpu_group", group)
    buf = _SymmetricMemory.empty_strided_p2p(
        (shape[0] * shape[1],),
        [1],
        dtype,
        torch.device("cuda", torch.cuda.current_device()),
        pg.group_name,
    )
    mc_ptr = int(_SymmetricMemory.rendezvous(buf).multicast_ptr)
    return buf.view(shape), mc_ptr


class NVLinkVocabGather(VocabGather):
    """The NVLink collectives on CustomAllReduceV2's multicast plane.

    A slice that fits one slot of the push plane takes the push kernel into a
    fresh tensor; a larger one that fits ``pull_out`` takes the pull kernel into
    that symmetric-memory output, which is reused every call; anything else goes
    to ``fallback``, the NCCL ring. Both kernels gather along the row axis, so
    the ranks come back stacked and are transposed into place. ``pull_out`` is
    allocated here: the allocation is collective and captured graphs keep its
    address.
    """

    def __init__(
        self,
        *,
        ca_comm,
        group,
        local_width: int,
        dtype: torch.dtype,
        symm_rows: int,
        fallback: VocabGather,
    ) -> None:
        self.comm = ca_comm.obj
        self.world_size = int(group.world_size)
        self.slot_bytes = int(ca_comm.max_push_size)
        self.fallback = fallback
        self.pull_out: Optional[torch.Tensor] = None
        self.pull_mc_ptr = 0
        if symm_rows > 0 and self.comm.pull is not None:
            out, mc_ptr = _alloc_symm(
                group, (self.world_size * symm_rows, local_width), dtype
            )
            if mc_ptr != 0:
                self.pull_out, self.pull_mc_ptr = out, mc_ptr
                logger.info(
                    "NVLink vocab gather: pull output %s (%d MB)",
                    tuple(out.shape),
                    out.numel() * out.element_size() >> 20,
                )
            else:
                logger.warning("NVLink vocab gather: no multicast alias, pull path off")

    def __call__(self, local: torch.Tensor) -> torch.Tensor:
        rows = local.shape[0]
        if local.nbytes <= self.slot_bytes:
            return self._push(local)
        total_rows = self.world_size * rows
        if self.pull_out is not None and total_rows <= self.pull_out.shape[0]:
            return self._pull(local, self.pull_out[:total_rows])
        return self.fallback(local)

    def gather_stacked(self, local: torch.Tensor) -> torch.Tensor:
        # Compact argmax partials need rank-major output, no symmetric pull buffer.
        if (
            local.is_contiguous()
            and local.shape[1] * local.element_size() % 16 == 0
            and local.nbytes <= self.slot_bytes
        ):
            return self._push_stacked(local)
        return self.fallback.gather_stacked(local)

    def _push(self, local: torch.Tensor) -> torch.Tensor:
        return self._unstack(self._push_stacked(local))

    def _push_stacked(self, local: torch.Tensor) -> torch.Tensor:
        from sglang.kernels.ops.communication import nvlink_comm

        rows, width = local.shape
        gathered = torch.empty(
            (self.world_size * rows, width), dtype=local.dtype, device=local.device
        )
        nvlink_comm.all_gather_push(self.comm, local, gathered)
        return gathered

    def _pull(self, local: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        from sglang.kernels.ops.communication import nvlink_comm

        nvlink_comm.all_gather_pull(self.comm, local, out, out_mc_ptr=self.pull_mc_ptr)
        full = self._unstack(out)
        # the transpose copies except at one row, where it would alias the
        # shared buffer that the next call overwrites
        return full.clone() if full.data_ptr() == out.data_ptr() else full

    def _unstack(self, gathered: torch.Tensor) -> torch.Tensor:
        rows = gathered.shape[0] // self.world_size
        width = gathered.shape[1]
        if rows == 1:
            return gathered.view(1, self.world_size * width)
        return (
            gathered.view(self.world_size, rows, width)
            .transpose(0, 1)
            .reshape(rows, self.world_size * width)
        )


def _nvlink_ca_comm(group, *, local_width: int, dtype: torch.dtype):
    ca_comm = getattr(group, "ca_comm", None)
    if ca_comm is None or getattr(ca_comm, "disabled", True):
        return None
    comm = getattr(ca_comm, "obj", None)
    if comm is None or not getattr(ca_comm, "has_multicast", False):
        return None
    if comm.push is None or comm.world_size != group.world_size:
        return None
    # the kernels move 16-byte vectors along the row
    if local_width % (128 // torch.finfo(dtype).bits) != 0:
        return None
    return ca_comm


def _default_symm_rows() -> int:
    try:
        from sglang.srt.runtime_context import get_exec, get_schedule

        return int(
            get_schedule().max_running_requests
            or get_exec().graph.cuda_graph_config.decode.max_bs
            or 0
        )
    except Exception:
        return 0


def make_vocab_gather(
    group,
    *,
    local_width: int,
    dtype: torch.dtype = torch.float32,
    prefer_nvlink: bool = True,
    symm_rows: Optional[int] = None,
) -> VocabGather:
    """The gather for ``group``: local for a group of one, NVLink when the
    group's custom all-reduce has a multicast plane (and ``prefer_nvlink``),
    the NCCL ring otherwise. ``symm_rows`` is the row capacity of the NVLink
    gather's symmetric-memory output for slices past the push slot; None sizes
    it for the server's largest batch, 0 leaves those slices to NCCL."""
    if group is None or group.world_size == 1:
        return LocalVocabGather()
    nccl = NcclVocabGather(group)
    if not prefer_nvlink:
        return nccl
    ca_comm = _nvlink_ca_comm(group, local_width=local_width, dtype=dtype)
    if ca_comm is None:
        return nccl
    return NVLinkVocabGather(
        ca_comm=ca_comm,
        group=group,
        local_width=local_width,
        dtype=dtype,
        symm_rows=_default_symm_rows() if symm_rows is None else symm_rows,
        fallback=nccl,
    )

import logging
import threading
import time
from typing import Optional

import torch
import torch.distributed as dist
import uvicorn
from fastapi import FastAPI
from fastapi.responses import PlainTextResponse

from sglang.srt.distributed.parallel_state import get_world_group

logger = logging.getLogger(__name__)

POLL_INTERVAL_SECONDS = 1.0
LOG_INTERVAL_SECONDS = 10.0

_instance: Optional["_GatedLaunchServer"] = None


def maybe_wait_for_gated_launch(*, host: str, port: Optional[int]) -> None:
    global _instance

    if port is None or _instance is not None:
        return

    world_group = get_world_group()

    _instance = _GatedLaunchServer()
    if world_group.rank_in_group == 0:
        _instance.serve(host=host, port=port)

    logger.info(f"Gated launch waiting for activation. rank={world_group.rank}")
    tic = time.perf_counter()
    _wait_until_activated(world_group=world_group, server=_instance)
    logger.info(f"Gated launch activated. elapsed={time.perf_counter() - tic:.2f} s")


def _wait_until_activated(*, world_group, server: "_GatedLaunchServer") -> None:
    activated = torch.zeros(1, dtype=torch.int32)
    started_at = time.perf_counter()
    next_log_at = started_at + LOG_INTERVAL_SECONDS

    while True:
        activated[0] = int(server.activated)

        if world_group.world_size > 1:
            dist.broadcast(
                activated,
                src=world_group.ranks[0],
                group=world_group.cpu_group,
            )

        if bool(activated[0]):
            return

        if (now := time.perf_counter()) >= next_log_at:
            logger.info(
                f"Gated launch still waiting for activation. "
                f"rank={world_group.rank} elapsed={now - started_at:.0f} s"
            )
            next_log_at = now + LOG_INTERVAL_SECONDS

        time.sleep(POLL_INTERVAL_SECONDS)


class _GatedLaunchServer:
    def __init__(self):
        self.activated = False
        self._server: Optional[uvicorn.Server] = None
        self._thread: Optional[threading.Thread] = None

    def serve(self, *, host: str, port: int) -> None:
        config = uvicorn.Config(
            _build_app(self), host=host, port=port, log_level="warning"
        )
        self._server = uvicorn.Server(config)
        self._thread = threading.Thread(target=self._server.run, daemon=True)
        self._thread.start()
        logger.info(f"Gated launch control server started on {host}:{port}")


def _build_app(server: _GatedLaunchServer) -> FastAPI:
    app = FastAPI()

    @app.get("/health")
    def health():
        return PlainTextResponse("OK")

    @app.post("/gate/activate")
    def activate():
        server.activated = True
        return PlainTextResponse("OK")

    return app

import pickle
import time
from pathlib import Path
from typing import Any, List, Optional

import pybase64
import torch

from sglang.srt.utils import MultiprocessingSerializer


class NaiveDistributed:
    def __init__(self, rank: int, world_size: int, rendezvous: str):
        self._rank = rank
        self._world_size = world_size
        self._operation_index = 0
        self._directory = Path(rendezvous)
        self._directory.mkdir(parents=True, exist_ok=True)
        assert 0 <= rank < world_size

        # both barrier to be safe, and as a sanity check
        self.barrier()

    def get_rank(self):
        return self._rank

    def get_world_size(self):
        return self._world_size

    def scatter(
        self, tensor: torch.Tensor, scatter_list: List[torch.Tensor], src: int = 0
    ):
        if self._rank == src:
            assert len(scatter_list) == self._world_size
        else:
            assert scatter_list is None

        gathered_objects = self.all_gather_object(
            dict(
                serialized_scatter_list=[
                    (
                        None
                        if item_rank == src
                        else MultiprocessingSerializer.serialize(item)
                    )
                    for item_rank, item in enumerate(scatter_list)
                ]
            )
            if self._rank == src
            else dict()
        )

        remote_serialized_tensor = gathered_objects[src]["serialized_scatter_list"][
            self._rank
        ]
        if self._rank == src:
            assert remote_serialized_tensor is None
            remote_tensor = scatter_list[self._rank]
        else:
            remote_tensor = MultiprocessingSerializer.deserialize(
                remote_serialized_tensor
            )
        tensor.copy_(remote_tensor)

        # avoid src tensor be deleted too early
        self.barrier()

    def all_gather_object(self, obj: Any) -> List[Any]:
        self._operation_index += 1

        text_postfix = "\n"

        def _get_path(interesting_rank: int):
            return (
                self._directory
                / f"rank{interesting_rank}_op{self._operation_index}.txt"
            )

        _get_path(self._rank).write_text(
            pybase64.b64encode(pickle.dumps(obj)).decode("utf-8") + text_postfix
        )

        def _read_one(interesting_rank: int):
            p = _get_path(interesting_rank)
            while True:
                if p.exists() and (text := p.read_text()).endswith(text_postfix):
                    return pickle.loads(
                        pybase64.b64decode(text[: -len(text_postfix)], validate=True)
                    )
                time.sleep(0.001)

        return [
            _read_one(interesting_rank) for interesting_rank in range(self._world_size)
        ]

    def barrier(self):
        actual_objs = self.all_gather_object(self._rank)
        assert actual_objs == list(range(self._world_size)), f"{actual_objs=}"


# Can have multi instances if needed
_instance: Optional[NaiveDistributed] = None


def get_naive_distributed():
    assert _instance is not None
    return _instance


def set_naive_distributed(instance: NaiveDistributed):
    global _instance
    assert _instance is None
    _instance = instance

